#!/usr/bin/env node
// Generated by autoorchestra. Enforces the model on subagent launches.
//
// - packet agents: the launch must carry an allowed model, either as the `model`
//   parameter or as a `model: <slug>` line in the prompt (copied into the parameter).
//   Otherwise the launch is denied.
// - pinned agents: a missing or different model is rewritten to the pinned one.
// - any other agent: passes through untouched.
//
// Config: orchestra-models.json next to this file (written by render.mjs).
// Works for Cursor (hooks.json: preToolUse / subagentStart) and Claude Code (PreToolUse).

import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));

function loadConfig() {
  try {
    return JSON.parse(readFileSync(join(here, 'orchestra-models.json'), 'utf8'));
  } catch {
    return null;
  }
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8');
  } catch {
    return '';
  }
}

export function normalize(model, cfg) {
  if (typeof model !== 'string') return null;
  const m = model.trim();
  if (!m) return null;
  if (cfg.aliases && typeof cfg.aliases[m] === 'string') return cfg.aliases[m];
  return m;
}

export function modelFromPrompt(prompt, cfg) {
  if (typeof prompt !== 'string') return null;
  for (const line of prompt.split(/\r?\n/)) {
    const hit = /^\s*model:\s*`?([^`\s]+)`?\s*$/i.exec(line);
    if (!hit) continue;
    const slug = normalize(hit[1], cfg);
    if (slug && cfg.packetAllowed.includes(slug)) return slug;
  }
  return null;
}

// Returns { action: 'allow' | 'deny' | 'update', input?, reason? }
export function decide(data, cfg) {
  const input = data && typeof data.tool_input === 'object' && data.tool_input ? data.tool_input : {};
  const agent = input.subagent_type || data.subagent_type || data.subagent_name || data.agent_type || '';
  const toolName = data.tool_name || data.tool || '';
  const canUpdate = toolName === 'Task' || toolName === 'Agent';

  if (!agent) return { action: 'allow' };
  const raw = input.model !== undefined ? input.model : data.model;
  const given = normalize(raw, cfg);

  if (cfg.packetAgents.includes(agent)) {
    if (given && cfg.packetAllowed.includes(given)) {
      if (given !== raw && canUpdate) return { action: 'update', input: { ...input, model: given } };
      return { action: 'allow' };
    }
    const found = modelFromPrompt(input.prompt !== undefined ? input.prompt : data.prompt, cfg);
    if (found) {
      if (canUpdate) return { action: 'update', input: { ...input, model: found } };
      return { action: 'allow' };
    }
    return {
      action: 'deny',
      reason:
        `Blocked ${agent} launch: pass the packet model exactly. Allowed: ${cfg.packetAllowed.join(', ')}. ` +
        `An omitted model may run on the wrong model. Relaunch scope if the packet has no model line.`,
    };
  }

  const pinned = cfg.pinned[agent];
  if (pinned) {
    if (given === pinned) return { action: 'allow' };
    if (!canUpdate) return { action: 'allow' };
    if (cfg.platform === 'claude' && !/^(haiku|sonnet|opus|fable)$/.test(pinned)) {
      // Per-launch model accepts aliases only; drop it so the frontmatter model applies.
      if (raw === undefined) return { action: 'allow' };
      const { model, ...rest } = input;
      return { action: 'update', input: rest };
    }
    if (cfg.platform === 'claude' && raw === undefined) return { action: 'allow' }; // frontmatter applies
    return { action: 'update', input: { ...input, model: pinned } };
  }

  return { action: 'allow' };
}

function emit(obj) {
  process.stdout.write(JSON.stringify(obj) + '\n');
}

export function respond(result, platform) {
  if (platform === 'claude') {
    if (result.action === 'allow') return null;
    if (result.action === 'deny')
      return {
        hookSpecificOutput: {
          hookEventName: 'PreToolUse',
          permissionDecision: 'deny',
          permissionDecisionReason: result.reason,
        },
      };
    return {
      hookSpecificOutput: {
        hookEventName: 'PreToolUse',
        permissionDecision: 'allow',
        permissionDecisionReason: 'autoorchestra: model set from the orchestration spec',
        updatedInput: result.input,
      },
    };
  }
  // Cursor
  if (result.action === 'allow') return { permission: 'allow' };
  if (result.action === 'deny') return { permission: 'deny', user_message: result.reason, agent_message: result.reason };
  return { permission: 'allow', updated_input: result.input };
}

function main() {
  const cfg = loadConfig();
  const platform = cfg ? cfg.platform : 'cursor';
  let data;
  try {
    data = JSON.parse(readStdin() || '{}');
  } catch {
    const out = respond({ action: 'allow' }, platform);
    if (out) emit(out);
    return;
  }
  if (!cfg) {
    process.stderr.write('autoorchestra: orchestra-models.json missing; allowing launch\n');
    const out = respond({ action: 'allow' }, platform);
    if (out) emit(out);
    return;
  }
  const out = respond(decide(data, cfg), cfg.platform);
  if (out) emit(out);
}

if (process.argv[1] && /require-model\.mjs$/.test(process.argv[1])) main();
